api.adaptor:
var items = payload.data || [];
function policyName(v){ if(v === 'app_catalog:on_demand') return '按需分发策略'; if(v === 'app_catalog:preload') return '启动前预分发策略'; if(v === 'app_catalog:broadcast') return '广播分发策略'; return v || '-'; }
function triggerCondition(v){ if(v === 'Fallback to on-demand distribution when no application policy is configured') return '未配置应用分发策略，默认采用按需分发'; return v || '-'; }
function triggerSource(v){ if(v === 'EDGE_EXECUTE') return '边缘任务执行'; if(v === 'TASK_START_PREWARM') return '任务启动前预分发'; return v || '-'; }
function message(v){ if(v === 'Application copied from center Harbor to edge registry') return '已从中心镜像仓库复制到边缘镜像仓库'; if(v === 'Application already exists in edge registry, reused directly') return '边缘镜像仓库已存在该应用，直接复用'; if(v === 'Checking edge registry and preparing application') return '正在检查边缘镜像仓库并准备应用'; return v || '-'; }
items = items.map(function(item){ return {...item, policyNameText: policyName(item.policyName), triggerConditionText: triggerCondition(item.triggerCondition), triggerSourceText: triggerSource(item.triggerSource), messageText: message(item.message)}; });
return {...payload, status: payload.status === 200 ? 0 : payload.status, msg: payload.message, data: {items: items}};
